import { Observation } from '@argus/schema';

const MAX_REDIRECTS = 5;
const REQUEST_TIMEOUT_MS = 8000;
const USER_AGENT = 'ARGUS/0.1 (Security Research Tool; +https://github.com/argus-security/argus)';

export interface HttpCollectorOptions {
  validateRedirect?: (url: string) => Promise<boolean>;
  maxRedirects?: number;
  timeoutMs?: number;
}

export interface HttpCollectionResult {
  observations: Observation[];
  finalUrl: string;
  redirectChain: string[];
}

export async function collectHttp(
  url: string,
  runId: string,
  targetId: string,
  options: HttpCollectorOptions = {}
): Promise<HttpCollectionResult> {
  const observations: Observation[] = [];
  const redirectChain: string[] = [url];
  const maxRedirects = options.maxRedirects ?? MAX_REDIRECTS;
  const timeoutMs = options.timeoutMs ?? REQUEST_TIMEOUT_MS;

  let currentUrl = url;
  let redirectCount = 0;
  const timestamp = new Date().toISOString();

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    while (redirectCount <= maxRedirects) {
      try {
        const response = await fetch(currentUrl, {
          redirect: 'manual',
          signal: controller.signal,
          headers: {
            'User-Agent': USER_AGENT,
            // No Cookie header
            // No Authorization header
          }
        });

        const headers: Record<string, string> = {};
        response.headers.forEach((value, key) => {
          const lowerKey = key.toLowerCase();
          // Do not persist Set-Cookie values
          if (lowerKey !== 'set-cookie') {
            headers[lowerKey] = value;
          }
        });

        observations.push({
          id: `obs_http_${currentUrl}_${Date.now()}_${redirectCount}`,
          runId,
          targetId,
          type: 'HTTP_RESPONSE',
          source: 'http',
          collector: 'argus-http-collector',
          collectorVersion: '0.1.0',
          observedAt: timestamp,
          rawValue: {
            status: response.status,
            url: currentUrl,
            redirectCount,
            headers
          }
        });

        // Check if this is a redirect
        if (response.status >= 300 && response.status < 400) {
          const location = response.headers.get('location');

          if (!location) {
            observations.push({
              id: `obs_http_err_${currentUrl}_${Date.now()}`,
              runId,
              targetId,
              type: 'HTTP_ERROR',
              source: 'http',
              collector: 'argus-http-collector',
              collectorVersion: '0.1.0',
              observedAt: timestamp,
              rawValue: {
                error: 'REDIRECT_WITHOUT_LOCATION',
                message: 'Redirect response missing Location header',
                status: response.status,
                url: currentUrl
              }
            });
            break;
          }

          // Resolve relative redirects
          const nextUrl = new URL(location, currentUrl).toString();

          // Validate redirect destination
          if (options.validateRedirect) {
            const isValid = await options.validateRedirect(nextUrl);
            if (!isValid) {
              observations.push({
                id: `obs_http_err_${currentUrl}_${Date.now()}`,
                runId,
                targetId,
                type: 'HTTP_ERROR',
                source: 'http',
                collector: 'argus-http-collector',
                collectorVersion: '0.1.0',
                observedAt: timestamp,
                rawValue: {
                  error: 'REDIRECT_TO_FORBIDDEN_TARGET',
                  message: 'Redirect destination failed policy validation',
                  from: currentUrl,
                  to: nextUrl
                }
              });
              break;
            }
          }

          redirectCount++;
          if (redirectCount > maxRedirects) {
            observations.push({
              id: `obs_http_err_${currentUrl}_${Date.now()}`,
              runId,
              targetId,
              type: 'HTTP_ERROR',
              source: 'http',
              collector: 'argus-http-collector',
              collectorVersion: '0.1.0',
              observedAt: timestamp,
              rawValue: {
                error: 'TOO_MANY_REDIRECTS',
                message: `Exceeded maximum of ${maxRedirects} redirects`,
                url: currentUrl,
                redirectCount
              }
            });
            break;
          }

          redirectChain.push(nextUrl);
          currentUrl = nextUrl;
          continue;
        }

        // Not a redirect, we're done
        break;
      } catch (error: any) {
        clearTimeout(timeoutId);

        const errorType = error.name === 'AbortError' ? 'TIMEOUT' : 'FETCH_ERROR';
        const errorMessage = error.name === 'AbortError'
          ? `Request timeout after ${timeoutMs}ms`
          : error.message;

        observations.push({
          id: `obs_http_err_${currentUrl}_${Date.now()}`,
          runId,
          targetId,
          type: 'HTTP_ERROR',
          source: 'http',
          collector: 'argus-http-collector',
          collectorVersion: '0.1.0',
          observedAt: timestamp,
          rawValue: {
            error: errorType,
            message: errorMessage,
            url: currentUrl
          }
        });
        break;
      }
    }
  } finally {
    clearTimeout(timeoutId);
  }

  return {
    observations,
    finalUrl: currentUrl,
    redirectChain
  };
}
